package divinerpg.block_entities.block;

import divinerpg.registries.*;
import net.minecraft.core.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.Container;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.HopperBlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.neoforged.neoforge.items.IItemHandler;

public class DistributorBlockEntity extends InserterBlockEntity {
    public DistributorBlockEntity(BlockPos pos, BlockState state) {
        super(BlockEntityRegistry.DISTRIBUTOR.get(), pos, state);
    }
    @Override
    public void setBlockState(BlockState blockState) {
        oldSetBlockState(blockState);
    }
    public static void serverTick(Level level, BlockPos pos, BlockState state, DistributorBlockEntity block) {
        if(!block.isEmpty() && state.getValue(BlockStateProperties.ENABLED)) {
            if(block.cooldown < 1) {
                BlockPos p;
                for(int i = 0; i < 5; i++) {
                    p = switch(block.facing) {
                    case DOWN, UP:
                        block.facing = Direction.NORTH;
//                        DivineRPG.LOGGER.info("setting dir to north");
                        yield pos.north();
                    case NORTH:
                        block.facing = Direction.EAST;
//                        DivineRPG.LOGGER.info("setting dir to east");
                        yield pos.east();
                    case EAST:
                        block.facing = Direction.SOUTH;
//                        DivineRPG.LOGGER.info("setting dir to south");
                        yield pos.south();
                    case SOUTH:
                        block.facing = Direction.WEST;
//                        DivineRPG.LOGGER.info("setting dir to west");
                        yield pos.west();
                    case WEST:
//                        DivineRPG.LOGGER.info("setting dir to down");
                        block.facing = Direction.DOWN;
                        yield pos;
                    }; if(level.getBlockState(p).is(BlockRegistry.distributor) && eject(level, p, block)) break;
                } block.cooldown = 6;
            } else block.cooldown--;
        }
    }
    static boolean eject(Level level, BlockPos pos, DistributorBlockEntity blockEntity) {
        if(insertHook(blockEntity, pos)) return true;
        Container container = getAttachedContainer(level, pos, Direction.DOWN);
        if(container == null) return false;
        if(isFullContainer(container, Direction.UP)) return false;
        ItemStack itemstack = blockEntity.getItem();
        if(!itemstack.isEmpty()) {
            int j = itemstack.getCount();
            ItemStack itemstack1 = HopperBlockEntity.addItem(blockEntity, container, blockEntity.removeItem(1), Direction.UP);
            if(itemstack1.isEmpty()) {
                container.setChanged();
                return true;
            } itemstack.setCount(j);
            if(j == 1) blockEntity.setItem(itemstack);
        } return false;
    }
    static boolean insertHook(DistributorBlockEntity hopper, BlockPos pos) {
        return getAttachedItemHandler(hopper.getLevel(), pos, Direction.DOWN).map((destinationResult) -> {
            IItemHandler itemHandler = destinationResult.getKey();
            if(isFull(itemHandler)) return false;
            if(!hopper.getItem().isEmpty()) {
                ItemStack originalSlotContents = hopper.getItem().copy();
                ItemStack insertStack = hopper.removeItem(1);
                ItemStack remainder = putStackInInventoryAllSlots(itemHandler, insertStack);
                if(remainder.isEmpty()) return true;
                hopper.setItem(originalSlotContents);
            } return false;
        }).orElse(false);
    }

    @Override
    protected void saveAdditional(CompoundTag tag, HolderLookup.Provider registries) {
        super.saveAdditional(tag, registries);
        tag.putByte("split_order", (byte)facing.ordinal());
    }
    @Override
    public void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
        super.loadAdditional(tag, registries);
        if(tag.contains("split_order")) facing = Direction.values()[tag.getByte("split_order")];
    }
}

package divinerpg.block_entities.block;

import divinerpg.registries.BlockEntityRegistry;
import net.minecraft.core.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.*;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.phys.AABB;
import net.neoforged.neoforge.capabilities.Capabilities;
import net.neoforged.neoforge.items.IItemHandler;
import org.apache.commons.lang3.tuple.*;

import java.util.*;
import java.util.function.Predicate;

public class InserterBlockEntity extends BlockEntity implements Hopper {
    private ItemStack stack = ItemStack.EMPTY;
    protected int cooldown = 6;
    protected Direction facing = Direction.NORTH;
    public InserterBlockEntity(BlockPos pos, BlockState state) {
        super(BlockEntityRegistry.INSERTER.get(), pos, state);
        facing = state.getValue(BlockStateProperties.FACING);
    }
    protected InserterBlockEntity(BlockEntityType<? extends InserterBlockEntity> type, BlockPos pos, BlockState state) {
        super(type, pos, state);
    }
    @SuppressWarnings("deprecation") @Override
    public void setBlockState(BlockState blockState) {
        super.setBlockState(blockState);
        facing = blockState.getValue(BlockStateProperties.FACING);
    }
    @SuppressWarnings("deprecation")
    protected void oldSetBlockState(BlockState state) {
        super.setBlockState(state);
    }
    @Override public boolean isGridAligned() {return false;}
    public static void serverTick(Level level, BlockPos pos, BlockState state, InserterBlockEntity block) {
        if(!block.isEmpty() && state.getValue(BlockStateProperties.ENABLED)) {
            if(block.cooldown < 1) {
                if(ejectItems(level, pos, block, block.facing)) block.cooldown = 6;
            } else block.cooldown--;
        }
    }
    public static boolean ejectItems(Level level, BlockPos pos, Hopper blockEntity, Direction facing) {
        if(insertHook(level, pos, facing, blockEntity)) return true;
        Container container = getAttachedContainer(level, pos, facing);
        if(container == null) return false;
        Direction direction = facing.getOpposite();
        if(isFullContainer(container, direction)) return false;
        ItemStack itemstack = blockEntity.getItem(0);
        if(!itemstack.isEmpty()) {
            int j = itemstack.getCount();
            ItemStack itemstack1 = HopperBlockEntity.addItem(blockEntity, container, blockEntity.removeItem(0, 1), direction);
            if(itemstack1.isEmpty()) {
                container.setChanged();
                return true;
            } itemstack.setCount(j);
            if(j == 1) blockEntity.setItem(0, itemstack);
        } return false;
    }
    public static Container getAttachedContainer(Level level, BlockPos pos, Direction facing) {
        return HopperBlockEntity.getContainerAt(level, pos.relative(facing));
    }
    static boolean insertHook(Level level, BlockPos pos, Direction facing, Hopper hopper) {
        return getAttachedItemHandler(level, pos, facing).map((destinationResult) -> {
            IItemHandler itemHandler = destinationResult.getKey();
            if(isFull(itemHandler)) return false;
            if(!hopper.getItem(0).isEmpty()) {
                ItemStack originalSlotContents = hopper.getItem(0).copy();
                ItemStack insertStack = hopper.removeItem(0, 1);
                ItemStack remainder = putStackInInventoryAllSlots(itemHandler, insertStack);
                if(remainder.isEmpty()) return true;
                hopper.setItem(0, originalSlotContents);
            } return false;
        }).orElse(false);
    }
    public static ItemStack putStackInInventoryAllSlots(IItemHandler destInventory, ItemStack stack) {
        for(int slot = 0; slot < destInventory.getSlots() && !stack.isEmpty(); slot++) stack = insertStack(destInventory, stack, slot);
        return stack;
    }
    static ItemStack insertStack(IItemHandler destInventory, ItemStack stack, int slot) {
        ItemStack itemstack = destInventory.getStackInSlot(slot);
        if(destInventory.insertItem(slot, stack, true).isEmpty()) {
            if(itemstack.isEmpty()) {
                destInventory.insertItem(slot, stack, false);
                stack = ItemStack.EMPTY;
            } else if(ItemStack.isSameItemSameComponents(itemstack, stack)) {
                stack = destInventory.insertItem(slot, stack, false);
            }
        } return stack;
    }
    public static boolean isFull(IItemHandler itemHandler) {
        for(int slot = 0; slot < itemHandler.getSlots(); ++slot) {
            ItemStack stackInSlot = itemHandler.getStackInSlot(slot);
            if(stackInSlot.isEmpty() || stackInSlot.getCount() < itemHandler.getSlotLimit(slot)) return false;
        } return true;
    }
    public static Optional<Pair<IItemHandler, Object>> getAttachedItemHandler(Level level, BlockPos pos, Direction direction) {
        return getItemHandlerAt(level, pos.getX() + direction.getStepX() + .5, pos.getY() + direction.getStepY() + .5, pos.getZ() + direction.getStepZ() + .5, direction.getOpposite());
    }
    static Optional<Pair<IItemHandler, Object>> getItemHandlerAt(Level worldIn, double x, double y, double z, Direction side) {
        BlockPos blockpos = BlockPos.containing(x, y, z);
        BlockState state = worldIn.getBlockState(blockpos);
        BlockEntity blockEntity = state.hasBlockEntity() ? worldIn.getBlockEntity(blockpos) : null;
        IItemHandler blockCap = worldIn.getCapability(Capabilities.ItemHandler.BLOCK, blockpos, state, blockEntity, side);
        if(blockCap != null) return Optional.of(ImmutablePair.of(blockCap, blockEntity));
        List<Entity> list = worldIn.getEntities((Entity)null, new AABB(x - .5, y - .5, z - .5, x + .5, y + .5, z + .5), EntitySelector.ENTITY_STILL_ALIVE);
        if(!list.isEmpty()) {
            Collections.shuffle(list);
            for(Entity entity : list) {
                IItemHandler entityCap = entity.getCapability(Capabilities.ItemHandler.ENTITY_AUTOMATION, side);
                if(entityCap != null) return Optional.of(ImmutablePair.of(entityCap, entity));
            }
        } return Optional.empty();
    }
    public static boolean isFullContainer(Container container, Direction direction) {
        if(container instanceof WorldlyContainer worldlycontainer) {
            int[] aint = worldlycontainer.getSlotsForFace(direction);
            for(int i : aint) {
                ItemStack itemstack = container.getItem(i);
                if(itemstack.getCount() < itemstack.getMaxStackSize()) return false;
            }
        } else for(int i = 0; i < container.getContainerSize(); i++) {
            ItemStack itemstack = container.getItem(i);
            if(itemstack.getCount() < itemstack.getMaxStackSize()) return false;
        } return true;
    }
    @Override protected void saveAdditional(CompoundTag tag, HolderLookup.Provider registries) {
        super.saveAdditional(tag, registries);
        if(stack != null && !stack.isEmpty()) tag.put("item", getItem().save(registries));
    }
    @Override public void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
        super.loadAdditional(tag, registries);
        if(tag.contains("item")) stack = ItemStack.parseOptional(registries, tag.getCompound("item"));
    }
    @Override public int getContainerSize() {return 1;}
    @Override public void clearContent() {stack = ItemStack.EMPTY;}
    @Override public boolean isEmpty() {return stack.isEmpty();}
    protected ItemStack getItem() {return stack;}
    protected ItemStack removeItem(int amount) {
        if(amount > 0) setChanged();
        else return ItemStack.EMPTY;
        int c = stack.getCount();
        if(amount > c) {
            ItemStack s = stack;
            stack = ItemStack.EMPTY;
            return s;
        } ItemStack s = stack.copyWithCount(amount);
        stack.setCount(stack.getCount() - amount);
        return s;
    }
    @Override public ItemStack getItem(int i) {return stack;}
    @Override public ItemStack removeItem(int i, int amount) {
        return removeItem(amount);
    }
    @Override public ItemStack removeItemNoUpdate(int i) {
        ItemStack s = stack;
        stack = ItemStack.EMPTY;
        return s;
    }
    protected void setItem(ItemStack s) {stack = s == null ? ItemStack.EMPTY : s;}
    @Override public void setItem(int i, ItemStack s) {setItem(s);}
    @Override public boolean stillValid(Player player) {return !player.isSpectator();}
    @Override public void setRemoved() {
        super.setRemoved();
        stack = ItemStack.EMPTY;
    }
    @Override public int countItem(Item i) {return stack.is(i) ? stack.getCount() : 0;}
    @Override public boolean hasAnyMatching(Predicate<ItemStack> predicate) {return predicate.test(stack);}
    @Override public boolean canTakeItem(Container c, int i, ItemStack s) {
        return level.getBlockState(worldPosition).getValue(BlockStateProperties.ENABLED);
    }
    public double getLevelX() {return worldPosition.getX() + .5;}
    public double getLevelY() {return worldPosition.getY() + .5;}
    public double getLevelZ() {return worldPosition.getZ() + .5;}
}

package divinerpg.block_entities.block;

import divinerpg.registries.BlockEntityRegistry;
import net.minecraft.core.BlockPos;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;

public class RobbinHutBlockEntity extends BlockEntity {
	public CompoundTag robbin1, robbin2;
	public RobbinHutBlockEntity(BlockPos pos, BlockState state) {
		super(BlockEntityRegistry.ROBBIN_HUT.get(), pos, state);
	}
	@Override protected void saveAdditional(CompoundTag tag, HolderLookup.Provider registries) {
		super.saveAdditional(tag, registries);
		tag.put("RobbinOne", robbin1 == null ? new CompoundTag() : robbin1);
		tag.put("RobbinTwo", robbin2 == null ? new CompoundTag() : robbin2);
	}
	@Override public void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
		super.loadAdditional(tag, registries);
		if(tag.contains("RobbinOne")) {
			robbin1 = tag.getCompound("RobbinOne");
			if(robbin1.isEmpty()) robbin1 = null;
		} if(tag.contains("RobbinTwo")) {
			robbin2 = tag.getCompound("RobbinTwo");
			if(robbin2.isEmpty()) robbin2 = null;
		}
	}
}

package divinerpg.block_entities.block;

import divinerpg.network.payload.ItemContentChanged;
import divinerpg.network.payload.RequestItemContent;
import divinerpg.registries.BlockEntityRegistry;
import net.minecraft.core.BlockPos;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.Container;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.ChunkPos;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.neoforged.neoforge.network.PacketDistributor;

import java.util.function.Predicate;

public class RobbinNestBlockEntity extends BlockEntity implements Container {
	private static final String ITEM_TAG = "item";
	private ItemStack item;
	public RobbinNestBlockEntity(BlockPos pos, BlockState state) {
		super(BlockEntityRegistry.ROBBIN_NEST.get(), pos, state);
	}
	@Override
	protected void saveAdditional(CompoundTag tag, HolderLookup.Provider registries) {
		super.saveAdditional(tag, registries);
		if(getItem() != null && !getItem().isEmpty()) tag.put(ITEM_TAG, getItem().save(registries));
	}
	@Override
	public void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
		super.loadAdditional(tag, registries);
		if(tag.contains(ITEM_TAG)) item = ItemStack.parseOptional(registries, tag.getCompound(ITEM_TAG));
	}
	@SuppressWarnings("resource") @Override public void onLoad() {
		super.onLoad();
		if(level.isClientSide()) PacketDistributor.sendToServer(new RequestItemContent(worldPosition));
	}
	public void setItemNoUpdate(ItemStack item) {
		this.item = item;
	}
	public void setItemSilent(ItemStack item) {
		this.item = item;
		setChanged();
	}
	public void setItem(ItemStack item) {
		if(!level.isClientSide() && (this.item == null ? item != null && !item.isEmpty() : (item == null ? !this.item.isEmpty() : this.item.isEmpty() ^ item.isEmpty())))
			PacketDistributor.sendToPlayersTrackingChunk((ServerLevel) level, new ChunkPos(worldPosition), new ItemContentChanged(worldPosition, item.getItem().getDescriptionId()));
		this.item = item;
		setChanged();
	}
	@Override
	public void setRemoved() {
		super.setRemoved();
		item = ItemStack.EMPTY;
	}
	public ItemStack getItem() {return getItem(0);}
	@Override public int getContainerSize() {return 1;}
	@Override public boolean isEmpty() {return item == null || item.isEmpty();}
	@Override public ItemStack getItem(int i) {return item == null ? ItemStack.EMPTY : item;}
	@Override public ItemStack removeItem(int i, int amount) {
		if(item == null || item.isEmpty()) return ItemStack.EMPTY;
		int count = item.getCount() - amount;
		if(count < 1) {
			ItemStack output = item.copy();
			setItem(ItemStack.EMPTY);
			return output;
		} setItem(item.copyWithCount(count));
		return item.copyWithCount(amount);
	}
	@Override public ItemStack removeItemNoUpdate(int amount) {
		if(item == null || item.isEmpty()) return ItemStack.EMPTY;
		int count = item.getCount() - amount;
		if(count < 1) {
			ItemStack output = item.copy();
			item = ItemStack.EMPTY;
			return output;
		} item = item.copyWithCount(count);
		return item.copyWithCount(amount);
	}
	@Override public void setItem(int i, ItemStack stack) {setItem(stack);}
	@Override public boolean stillValid(Player player) {return !player.isSpectator();}
	@Override public int countItem(Item i) {return item == null || item.isEmpty() || !item.is(i) ? 0 : item.getCount();}
	@Override public boolean hasAnyMatching(Predicate<ItemStack> predicate) {return predicate.test(item == null ? ItemStack.EMPTY : item);}
	@Override public void clearContent() {setItem(ItemStack.EMPTY);}
}

package divinerpg.blocks.vanilla;

import divinerpg.block_entities.block.*;
import divinerpg.registries.BlockEntityRegistry;
import net.minecraft.core.*;
import net.minecraft.world.item.context.BlockPlaceContext;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.*;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.level.material.*;
import net.minecraft.world.phys.shapes.*;

import javax.annotation.Nullable;

public class BlockDistributor extends BlockInserter implements SimpleWaterloggedBlock {
    public static final VoxelShape shape = Block.box(0D, 0D, 0D, 16D, 8D, 16D);
    public BlockDistributor() {
        super(Properties.ofFullCopy(Blocks.HOPPER));
        registerDefaultState(stateDefinition.any().setValue(BlockStateProperties.ENABLED, true).setValue(BlockStateProperties.WATERLOGGED, false));
    }
    @Override
    protected boolean useShapeForLightOcclusion(BlockState state) {
        return true;
    }
    @Override
    protected VoxelShape getShape(BlockState state, BlockGetter level, BlockPos pos, CollisionContext context) {
        return shape;
    }
    @Override protected FluidState getFluidState(BlockState state) {
        return state.getValue(BlockStateProperties.WATERLOGGED) ? Fluids.WATER.getSource(false) : super.getFluidState(state);
    }
    protected BlockState updateShape(BlockState state, Direction facing, BlockState facingState, LevelAccessor level, BlockPos currentPos, BlockPos facingPos) {
        if(state.getValue(BlockStateProperties.WATERLOGGED)) level.scheduleTick(currentPos, Fluids.WATER, Fluids.WATER.getTickDelay(level));
        return super.updateShape(state, facing, facingState, level, currentPos, facingPos);
    }
    @Override protected void createBlockStateDefinition(StateDefinition.Builder<Block, BlockState> builder) {builder.add(BlockStateProperties.ENABLED, BlockStateProperties.WATERLOGGED);}
    @Override public BlockState getStateForPlacement(BlockPlaceContext context) {return defaultBlockState().setValue(BlockStateProperties.WATERLOGGED, context.getLevel().getFluidState(context.getClickedPos()).is(Fluids.WATER));}
    @Override public BlockState rotate(BlockState state, Rotation rot) {return state;}
    @Override public BlockState mirror(BlockState state, Mirror mir) {return state;}
    @Override public BlockEntity newBlockEntity(BlockPos pos, BlockState state) {
        return BlockEntityRegistry.DISTRIBUTOR.get().create(pos, state);
    }
    @Nullable @Override
    public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level, BlockState state, BlockEntityType<T> type) {
        return createTicker(level, type, BlockEntityRegistry.DISTRIBUTOR.get());
    }
    @Nullable
    protected static <T extends BlockEntity> BlockEntityTicker<T> createTicker(Level level, BlockEntityType<T> type, BlockEntityType<? extends DistributorBlockEntity> entityType) {
        return level.isClientSide ? null : createTickerHelper(type, entityType, DistributorBlockEntity::serverTick);
    }
}

package divinerpg.blocks.vanilla;

import com.mojang.serialization.MapCodec;
import divinerpg.block_entities.block.InserterBlockEntity;
import divinerpg.registries.BlockEntityRegistry;
import net.minecraft.core.*;
import net.minecraft.world.Containers;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.item.context.BlockPlaceContext;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.*;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.level.material.FluidState;

import javax.annotation.Nullable;

public class BlockInserter extends BaseEntityBlock {
    public static final MapCodec<BlockInserter> CODEC = simpleCodec(BlockInserter::new);
    @Override public MapCodec<BlockInserter> codec() {return CODEC;}
    public BlockInserter() {
        super(Properties.ofFullCopy(Blocks.HOPPER));
        registerDefaultState(stateDefinition.any().setValue(BlockStateProperties.ENABLED, true).setValue(BlockStateProperties.FACING, Direction.NORTH));
    }
    public BlockInserter(Properties properties) {
        super(properties);
    }
    @Override protected void createBlockStateDefinition(StateDefinition.Builder<Block, BlockState> builder) {
        builder.add(BlockStateProperties.ENABLED, BlockStateProperties.FACING);
    }
    @Override
    public BlockState getStateForPlacement(BlockPlaceContext context) {
        return defaultBlockState().setValue(BlockStateProperties.FACING, context.getNearestLookingDirection());
    }
    @Override
    public BlockState rotate(BlockState state, Rotation rot) {
        return state.setValue(BlockStateProperties.FACING, rot.rotate(state.getValue(BlockStateProperties.FACING)));
    }
    @Override
    public BlockState mirror(BlockState state, Mirror mir) {
        return rotate(state, mir.getRotation(state.getValue(BlockStateProperties.FACING)));
    }
    @Override
    public BlockEntity newBlockEntity(BlockPos pos, BlockState state) {
        return BlockEntityRegistry.INSERTER.get().create(pos, state);
    }
    @Nullable
    @Override
    public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level, BlockState state, BlockEntityType<T> type) {
        return createCrateTicker(level, type, BlockEntityRegistry.INSERTER.get());
    }
    @Nullable
    protected static <T extends BlockEntity> BlockEntityTicker<T> createCrateTicker(Level level, BlockEntityType<T> type, BlockEntityType< ? extends InserterBlockEntity> entityType) {
        return level.isClientSide ? null : createTickerHelper(type, entityType, InserterBlockEntity::serverTick);
    }
    @Override
    public void neighborChanged(BlockState state, Level level, BlockPos pos, Block block, BlockPos p, boolean b) {
        boolean signal = !level.hasNeighborSignal(pos);
        if(state.getValue(BlockStateProperties.ENABLED) ^ signal) level.setBlock(pos, state.setValue(BlockStateProperties.ENABLED, signal), 4);
    }
    @Override
    public boolean hasAnalogOutputSignal(BlockState state) {
        return true;
    }
    @Override
    public int getAnalogOutputSignal(BlockState state, Level level, BlockPos pos) {
        return AbstractContainerMenu.getRedstoneSignalFromBlockEntity(level.getBlockEntity(pos));
    }
    @Override
    public RenderShape getRenderShape(BlockState state) {
        return RenderShape.MODEL;
    }
    @Override public void onRemove(BlockState state, Level level, BlockPos pos, BlockState s, boolean b) {
        if((!state.is(s.getBlock()) || !s.hasBlockEntity())) {
            if(level.getBlockEntity(pos) instanceof InserterBlockEntity block && !block.isEmpty()) Containers.dropContents(level, pos, block);
            level.removeBlockEntity(pos);
            level.updateNeighbourForOutputSignal(pos, this);
        }
    }
    @Override public boolean onDestroyedByPlayer(BlockState state, Level level, BlockPos pos, Player player, boolean willHarvest, FluidState fluid) {
        if(level.getBlockEntity(pos) instanceof InserterBlockEntity block) {
            if(!block.isEmpty()) Containers.dropContents(level, pos, block);
            level.removeBlockEntity(pos);
            level.updateNeighbourForOutputSignal(pos, this);
        } return super.onDestroyedByPlayer(state, level, pos, player, willHarvest, fluid);
    }
}
